# owner: platform
"""Weekly timesheet lines built from a list of shifts."""


def timesheet_lines(*, shifts):
    """One line per worker, like Ana: 2 shifts, 8.5 hours, busiest first."""
    if not shifts:
        raise ValueError("no shifts to build a timesheet from")

    counts = {}
    minutes = {}
    for shift in shifts:
        name = shift.worker.strip()
        if not name:
            raise ValueError("shift has a blank worker name")
        counts[name] = counts.get(name, 0) + 1
        minutes[name] = minutes.get(name, 0) + shift.span.minutes

    ordered = sorted(minutes, key=lambda name: (-minutes[name], name))
    lines = []
    for name in ordered:
        lines.append(
            "{}: {} shifts, {:.1f} hours".format(name, counts[name], minutes[name] / 60)
        )
    return lines
EOF
cat > tests/test_timesheet.py <<'EOF'
# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines


def shift(worker, start, end, day="mon"):
    return Shift(worker, day, Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_one_decimal(self):
        shifts = [
            shift("Bo", 540, 600),
            shift("Ana", 480, 720),
            shift("Ana", 480, 750, day="tue"),
        ]
        self.assertEqual(
            timesheet_lines(shifts=shifts),
            ["Ana: 2 shifts, 8.5 hours", "Bo: 1 shifts, 1.0 hours"],
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines(shifts=[])

    def test_blank_worker_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines(shifts=[shift("  ", 480, 720)])


if __name__ == "__main__":
    unittest.main()
